import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { API_URL } from '../utils/api';

const History = () => {
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchHistory();
    // Refresh every 10 seconds
    const interval = setInterval(fetchHistory, 10000);
    return () => clearInterval(interval);
  }, []);

  const fetchHistory = async () => {
    try {
      const result = await axios.get(`${API_URL}/history`);
      setHistory(result.data.history || []);
      setError(null);
    } catch (err) {
      setError('Failed to load history: ' + err.message);
      setHistory([]);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div className="processor-container"><p>Loading history...</p></div>;
  }

  if (error) {
    return <div className="processor-container error-message">{error}</div>;
  }

  return (
    <div className="processor-container">
      <h2>Processing History</h2>
      
      <button onClick={fetchHistory} className="process-button">
        Refresh
      </button>

      {history.length === 0 ? (
        <p>No processing history yet.</p>
      ) : (
        <table style={{ width: '100%', marginTop: '20px', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ borderBottom: '2px solid #ccc' }}>
              <th style={{ padding: '10px', textAlign: 'left' }}>Type</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Output File</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Details</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Timestamp</th>
            </tr>
          </thead>
          <tbody>
            {history.map((item, index) => (
              <tr key={index} style={{ borderBottom: '1px solid #eee' }}>
                <td style={{ padding: '10px' }}>{item.type}</td>
                <td style={{ padding: '10px' }}>
                  {item.type === 'video' && item.output ? (
                    <a href={`${API_URL}/download/${item.output}`} download>
                      {item.output}
                    </a>
                  ) : (
                    item.output || '-'
                  )}
                </td>
                <td style={{ padding: '10px' }}>
                  {item.frames ? `${item.frames} frames` : '-'}
                </td>
                <td style={{ padding: '10px' }}>
                  {new Date(item.timestamp).toLocaleString()}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default History;
